const form=document.querySelector('#basic-info-form');const areaRow=document.querySelector('#area-row');const householdRow=document.querySelector('#household-row');const area=document.querySelector('#gross-area');const households=document.querySelector('#households');const approval=document.querySelector('#approval-date');
document.querySelectorAll('input[name="buildingType"]').forEach(input=>input.addEventListener('change',()=>{const apartment=input.value==='공동주택';area.disabled=apartment;area.required=!apartment;area.value=apartment?'':area.value;households.disabled=!apartment;households.required=apartment;households.value=apartment?households.value:'';areaRow.classList.toggle('disabled',apartment);householdRow.classList.toggle('disabled',!apartment);document.querySelector('#size-error').textContent=''}));
document.querySelector('#clear-renovation').addEventListener('click',()=>{document.querySelector('#renovation-date').value=''});
form.addEventListener('submit',event=>{event.preventDefault();const types=[...document.querySelectorAll('input[name="inspectionType"]:checked')].map(el=>el.value);const building=document.querySelector('input[name="buildingType"]:checked');document.querySelector('#inspection-error').textContent=types.length?'':'점검 구분을 하나 이상 선택해 주세요.';document.querySelector('#building-error').textContent=building?'':'건축물 용도를 선택해 주세요.';document.querySelector('#approval-error').textContent=approval.value?'':'사용승인일자를 입력해 주세요.';let sizeValid=false;if(building){sizeValid=building.value==='공동주택'?Number(households.value)>0:Number(area.value)>0}document.querySelector('#size-error').textContent=!building||sizeValid?'':building.value==='공동주택'?'세대수를 입력해 주세요.':'연면적을 입력해 주세요.';if(!types.length||!building||!approval.value||!sizeValid){document.querySelector('.error:not(:empty)')?.scrollIntoView({behavior:'smooth',block:'center'});return}const data={inspectionType:types.join(', '),buildingType:building.value,size:building.value==='공동주택'?`${Number(households.value).toLocaleString()} 세대`:`${Number(area.value).toLocaleString()} m²`,approvalDate:approval.value,renovationDate:document.querySelector('#renovation-date').value||'해당 없음'};sessionStorage.setItem('selfEstimateBasicInfo',JSON.stringify(data));document.querySelector('#saved-summary').innerHTML=Object.entries({'점검 구분':data.inspectionType,'건축물 용도':data.buildingType,'규모':data.size,'사용승인일자':data.approvalDate,'증축·개축·재축 및 대수선일자':data.renovationDate}).map(([key,value])=>`<div><small>${key}</small><b>${value}</b></div>`).join('');document.querySelector('#step-one').hidden=true;document.querySelector('#step-two').hidden=false;document.querySelectorAll('.step')[0].classList.remove('active');document.querySelectorAll('.step')[1].classList.add('active');window.scrollTo({top:0,behavior:'smooth'})});
document.querySelector('#back-to-one').addEventListener('click',()=>{document.querySelector('#step-two').hidden=true;document.querySelector('#step-one').hidden=false;document.querySelectorAll('.step')[1].classList.remove('active');document.querySelectorAll('.step')[0].classList.add('active');window.scrollTo({top:0,behavior:'smooth'})});
